// Fake DOM + fetch for running public/app.js in node:vm. The app only sees
// Proxies that throw on any member outside the allowed list.
import vm from 'node:vm';

const IDS = ['booking-form', 'room', 'title', 'date', 'start', 'end', 'book',
  'filter-date', 'show-all', 'booking-list', 'error'];
const EL_GET = ['textContent', 'value', 'type', 'disabled', 'append',
  'replaceChildren', 'addEventListener'];
const EL_SET = ['textContent', 'value', 'type', 'disabled'];

function forbid(prop) {
  return new Error('forbidden: ' + String(prop));
}

function allowOnly(target, getters, setters, label) {
  return new Proxy(target, {
    get(t, prop) {
      if (typeof prop === 'symbol') return undefined;
      if (!getters.includes(prop)) throw forbid(label + '.' + prop);
      return t[prop];
    },
    set(t, prop, value) {
      if (!setters.includes(prop)) throw forbid(label + '.' + prop);
      t[prop] = value;
      return true;
    },
  });
}

export function textOf(node) {
  return node.isText ? node.text : node.children.map(textOf).join('');
}

function makeInternal(tag, id = '') {
  return { tag, id, children: [], listeners: {}, value: '', type: '', disabled: false };
}

function toNode(arg, internals) {
  if (typeof arg === 'string') return { isText: true, text: arg };
  const node = internals.get(arg);
  if (!node) throw new Error('unknown node passed to append');
  return node;
}

function wrapElement(internal, internals) {
  const api = {
    append: (...args) => { internal.children.push(...args.map((a) => toNode(a, internals))); },
    replaceChildren: (...args) => { internal.children = args.map((a) => toNode(a, internals)); },
    addEventListener: (type, fn) => { (internal.listeners[type] ??= []).push(fn); },
    get value() { return internal.value; },
    set value(v) { internal.value = v; },
    get type() { return internal.type; },
    set type(v) { internal.type = v; },
    get disabled() { return internal.disabled; },
    set disabled(v) { internal.disabled = v; },
    get textContent() { return textOf(internal); },
    set textContent(v) {
      internal.children = v === '' ? [] : [{ isText: true, text: String(v) }];
    },
  };
  const proxy = allowOnly(api, EL_GET, EL_SET, 'element');
  internals.set(proxy, internal);
  return proxy;
}

function makeDocument(els, proxies, internals) {
  const api = {
    getElementById: (id) => proxies[id] ?? null,
    createElement: (tag) => wrapElement(makeInternal(tag), internals),
  };
  return allowOnly(api, ['getElementById', 'createElement'], [], 'document');
}

function makeResponse(status, body, opts, tracker) {
  const api = {
    status,
    json() {
      tracker.jsonCalled = true;
      if (opts.badJson) return Promise.reject(new SyntaxError('bad json'));
      const value = structuredClone(body);
      return opts.gate ? opts.gate.then(() => value) : Promise.resolve(value);
    },
  };
  return allowOnly(api, ['status', 'json'], [], 'response');
}

export function deferred() {
  let resolve; let reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

export function createPage(appSource) {
  const els = {};
  const proxies = {};
  const internals = new WeakMap();
  for (const id of IDS) {
    els[id] = makeInternal(id === 'booking-list' ? 'ul' : id, id);
    proxies[id] = wrapElement(els[id], internals);
  }
  const calls = [];
  const fetch = (url, options) => {
    const d = deferred();
    calls.push({ url, options, d, jsonCalled: false });
    return d.promise;
  };
  const document = makeDocument(els, proxies, internals);
  const ctx = vm.createContext({ document, fetch });
  const page = { els, calls, ctx, internals };
  page.run = () => vm.runInContext(appSource, ctx);
  return page;
}

export function respond(call, status, body, opts = {}) {
  call.d.resolve(makeResponse(status, body, opts, call));
}

export function respondBadJson(call, status) {
  respond(call, status, null, { badJson: true });
}

export function fail(call) {
  call.d.reject(new TypeError('fetch failed'));
}

export async function flush(times = 5) {
  for (let i = 0; i < times; i += 1) await new Promise((r) => setImmediate(r));
}

export function dispatch(el, type) {
  const record = { prevented: false };
  const event = allowOnly({ preventDefault: () => { record.prevented = true; } },
    ['preventDefault'], [], 'event');
  for (const fn of el.listeners[type] ?? []) fn(event);
  return record;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { readFileSync } from 'node:fs';
import {
  createPage, respond, respondBadJson, fail, flush, dispatch, deferred, textOf,
} from './app-fake-dom.mjs';

const html = readFileSync(new URL('../public/index.html', import.meta.url), 'utf8');
const appSrc = readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
const NO_REPLY = 'Could not reach the server.';
const B1 = { id: 1, room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00' };
const B2 = { id: 2, room: 'Cosmos', title: '<b>x</b>', date: '2026-11-03', start: '11:00', end: '12:00' };

// ---------- Part 1: static checks ----------

const formHtml = html.slice(html.indexOf('<form'), html.indexOf('</form>'));
const outside = html.replace(formHtml, '');

function labelText(id) {
  const m = html.match(new RegExp('<label[^>]*\\bfor="' + id + '"[^>]*>([\\s\\S]*?)</label>'));
  return m ? m[1] : null;
}

test('title and single h1', () => {
  assert.equal(html.match(/<title>([^<]*)<\/title>/)[1], 'Room bookings');
  const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/g)];
  assert.equal(h1s.length, 1);
  assert.equal(h1s[0][1], 'Room bookings');
});

test('form has novalidate and its controls', () => {
  assert.match(html, /<form\b[^>]*\bid="booking-form"[^>]*\bnovalidate\b/);
  assert.match(formHtml, /<select\b(?=[^>]*\bid="room")(?=[^>]*\bname="room")[^>]*>/);
  assert.match(formHtml, /<input\b(?=[^>]*\btype="text")(?=[^>]*\bid="title")(?=[^>]*\bname="title")[^>]*>/);
  assert.match(formHtml, /<input\b(?=[^>]*\btype="date")(?=[^>]*\bid="date")(?=[^>]*\bname="date")[^>]*>/);
  assert.match(formHtml, /<input\b(?=[^>]*\btype="time")(?=[^>]*\bid="start")(?=[^>]*\bname="start")[^>]*>/);
  assert.match(formHtml, /<input\b(?=[^>]*\btype="time")(?=[^>]*\bid="end")(?=[^>]*\bname="end")[^>]*>/);
  assert.match(formHtml, /<button\b(?=[^>]*\btype="submit")(?=[^>]*\bid="book")[^>]*>Book<\/button>/);
});

test('labels have exact text and do not wrap fields', () => {
  const expected = { room: 'Room', title: 'Title', date: 'Date', start: 'Start', end: 'End', 'filter-date': 'Show date' };
  for (const [id, text] of Object.entries(expected)) {
    const inner = labelText(id);
    assert.equal(inner, text, 'label for ' + id);
    assert.ok(!inner.includes('<'));
  }
});

test('controls outside the form', () => {
  assert.match(outside, /<input\b(?=[^>]*\btype="date")(?=[^>]*\bid="filter-date")[^>]*>/);
  assert.match(outside, /<button\b(?=[^>]*\btype="button")(?=[^>]*\bid="show-all")[^>]*>Show all<\/button>/);
  assert.match(outside, /<ul\b[^>]*\bid="booking-list"[^>]*>/);
  assert.match(outside, /<p\b(?=[^>]*\bid="error")(?=[^>]*\brole="alert")[^>]*><\/p>/);
});

test('script is the last element of body, single and plain', () => {
  const before = html.slice(0, html.indexOf('</body>')).trim();
  assert.ok(before.endsWith('<script src="/app.js"></script>'));
  assert.equal(html.match(/<script/g).length, 1);
  const tag = html.match(/<script[^>]*>/)[0];
  assert.doesNotMatch(tag, /\b(type|defer|async)\b/);
});

test('no rooms, handlers or absolute URLs in the page', () => {
  assert.doesNotMatch(html, /<option/);
  assert.doesNotMatch(html, /Aurora|Borealis|Cosmos/);
  assert.doesNotMatch(html, / on[a-z]+=/i);
  for (const src of [html, appSrc]) {
    assert.ok(!src.includes('http' + '://'));
    assert.ok(!src.includes('https' + '://'));
  }
  assert.doesNotMatch(appSrc, /^\s*(import|export)\b/m);
});

// ---------- Part 2: behaviour ----------

function load() {
  const page = createPage(appSrc);
  page.run();
  return page;
}

const listItems = (page) => page.els['booking-list'].children;
const errorText = (page) => textOf(page.els.error);
const listCalls = (page) => page.calls.filter((c) => c.url.startsWith('/api/bookings') && (!c.options || !c.options.method || c.options.method === 'GET'));
const isGet = (c) => !c.options || !c.options.method || c.options.method === 'GET';

async function renderList(page, bookings) {
  respond(page.calls[1], 200, { bookings });
  await flush();
}

function fillForm(page) {
  const v = { room: 'Aurora', title: '  Standup  ', date: '2026-11-03', start: '09:00', end: '10:00' };
  for (const [k, val] of Object.entries(v)) page.els[k].value = val;
  return v;
}

test('1. load starts rooms and list fetches synchronously', () => {
  const page = load();
  assert.equal(page.calls.length, 2);
  assert.equal(page.calls[0].url, '/api/rooms');
  assert.equal(page.calls[1].url, '/api/bookings');
  assert.ok(page.calls.every(isGet));
});

test('2. rooms fill the select', async () => {
  const page = load();
  respond(page.calls[0], 200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
  await flush();
  const opts = page.els.room.children;
  assert.equal(opts.length, 3);
  ['Aurora', 'Borealis', 'Cosmos'].forEach((n, i) => {
    assert.equal(opts[i].tag, 'option');
    assert.equal(opts[i].value, n);
    assert.equal(textOf(opts[i]), n);
  });
  assert.equal(errorText(page), '');

